using System;
using System.Linq;
using System.Collections.Generic;
using System.Text.RegularExpressions;

// Independent checker for this teaching example, not a substitute for Pyperplan tests.
public static class Week5Checks {
 class Expr {public string Atom;public List<Expr> Items=new List<Expr>();public override string ToString(){return Atom??"("+string.Join(" ",Items.Select(x=>x.ToString()))+")";}}
 class Op {public string Name;public HashSet<string> Pre,Add,Del;public bool Applicable(HashSet<string> s){return Pre.IsSubsetOf(s);}public HashSet<string> Apply(HashSet<string> s){var next=new HashSet<string>(s);next.ExceptWith(Del);next.UnionWith(Add);return next;}}
 static Expr Parse(string text) {var tokens=Regex.Matches(Regex.Replace(text,@";[^\r\n]*",""),@"\(|\)|[^\s()]+").Cast<Match>().Select(m=>m.Value).ToArray();int i=0;var e=Read(tokens,ref i);if(i!=tokens.Length)throw new Exception("Extra PDDL tokens");return e;}
 static Expr Read(string[] t,ref int i){if(i>=t.Length)throw new Exception("Incomplete PDDL");string atom=t[i++];if(atom!="(")return new Expr{Atom=atom};var e=new Expr();while(i<t.Length&&t[i]!=")")e.Items.Add(Read(t,ref i));if(i>=t.Length)throw new Exception("Unclosed PDDL");i++;return e;}
 static Expr Section(Expr e,string key){return e.Items.First(x=>x.Items.Count>0&&x.Items[0].Atom==key);}
 static Dictionary<string,string> Typed(IEnumerable<Expr> expressions){var list=expressions.Select(x=>x.Atom).ToArray();var result=new Dictionary<string,string>();var pending=new List<string>();for(int i=0;i<list.Length;i++){if(list[i]=="-"){string type=list[++i];foreach(string name in pending)result[name]=type;pending.Clear();}else pending.Add(list[i]);}foreach(string name in pending)result[name]="object";return result;}
 static string GroundFact(Expr e,Dictionary<string,string> binding){return "("+string.Join(" ",e.Items.Select(x=>binding.ContainsKey(x.Atom)?binding[x.Atom]:x.Atom))+")";}
 static IEnumerable<Expr> Conjuncts(Expr e){return e.Items[0].Atom=="and"?e.Items.Skip(1):new[]{e};}
 static void Instantiate(Expr action,Dictionary<string,string> types,Dictionary<string,string> objects,List<Op> operators,int index,Dictionary<string,string> binding){var names=types.Keys.ToArray();if(index<names.Length){string name=names[index];foreach(var item in objects.Where(x=>x.Value==types[name])){binding[name]=item.Key;Instantiate(action,types,objects,operators,index+1,binding);}binding.Remove(name);return;}var fields=action.Items;var pre=fields[fields.FindIndex(x=>x.Atom==":precondition")+1];var effect=fields[fields.FindIndex(x=>x.Atom==":effect")+1];var op=new Op{Name="("+fields[1].Atom+" "+string.Join(" ",names.Select(n=>binding[n]))+")",Pre=new HashSet<string>(Conjuncts(pre).Select(x=>GroundFact(x,binding))),Add=new HashSet<string>(),Del=new HashSet<string>()};foreach(var e in Conjuncts(effect)){if(e.Items[0].Atom=="not")op.Del.Add(GroundFact(e.Items[1],binding));else op.Add.Add(GroundFact(e,binding));}operators.Add(op);}
 static List<Op> Search(HashSet<string> initial,string goal,List<Op> ops){var seen=new HashSet<string>();var queue=new Queue<Tuple<HashSet<string>,List<Op>>>();queue.Enqueue(Tuple.Create(initial,new List<Op>()));while(queue.Count>0){var pair=queue.Dequeue();if(pair.Item1.Contains(goal))return pair.Item2;foreach(var op in ops.Where(x=>x.Applicable(pair.Item1))){var next=op.Apply(pair.Item1);string key=string.Join("|",next.OrderBy(x=>x,StringComparer.Ordinal));if(seen.Add(key)){var path=new List<Op>(pair.Item2);path.Add(op);queue.Enqueue(Tuple.Create(next,path));}}}return null;}
 static string Location(HashSet<string> state){return state.Single(x=>x.StartsWith("(robot-at ")).Split(' ')[1].TrimEnd(')');}
 public static double[][] Rectangles=new[]{new[]{2.8,3.2,0.0,2.8},new[]{2.8,3.2,3.2,4.8}};
 public static Dictionary<string,double[]> Positions=new Dictionary<string,double[]>{{"pickup",new[]{1.0,3.0}},{"delivery",new[]{5.0,3.0}},{"upper-left",new[]{2.0,5.4}},{"upper-right",new[]{4.0,5.4}}};
 static double Dist(double[] a,double[] b){return Math.Sqrt((a[0]-b[0])*(a[0]-b[0])+(a[1]-b[1])*(a[1]-b[1]));}
 static double PointSegment(double[] p,double[] a,double[] b){double dx=b[0]-a[0],dy=b[1]-a[1],den=dx*dx+dy*dy;double t=den==0?0:Math.Max(0,Math.Min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/den));return Dist(p,new[]{a[0]+t*dx,a[1]+t*dy});}
 static double PointRect(double[] p,double[] r){return Math.Sqrt(Math.Pow(Math.Max(0,Math.Max(r[0]-p[0],p[0]-r[1])),2)+Math.Pow(Math.Max(0,Math.Max(r[2]-p[1],p[1]-r[3])),2));}
 public static double SegmentRect(double[] a,double[] b,double[] r){double lo=0,hi=1;for(int axis=0;axis<2;axis++){double delta=b[axis]-a[axis],min=r[axis*2],max=r[axis*2+1];if(delta==0){if(a[axis]<min||a[axis]>max){lo=1;hi=0;break;}}else{double t0=(min-a[axis])/delta,t1=(max-a[axis])/delta;lo=Math.Max(lo,Math.Min(t0,t1));hi=Math.Min(hi,Math.Max(t0,t1));}}if(lo<=hi)return 0;var corners=new[]{new[]{r[0],r[2]},new[]{r[0],r[3]},new[]{r[1],r[2]},new[]{r[1],r[3]}};return Math.Min(Math.Min(PointRect(a,r),PointRect(b,r)),corners.Min(p=>PointSegment(p,a,b)));}
 public static bool Motion(double[] a,double[] b,double radius){return new[]{a,b}.All(p=>radius<p[0]&&p[0]<6-radius&&radius<p[1]&&p[1]<6-radius)&&Rectangles.All(r=>SegmentRect(a,b,r)>radius+1e-12);}
 static double Radius(HashSet<string> s){return s.Any(x=>x.StartsWith("(holding "))?.25:.12;}
 static int Validate(List<Op> path,HashSet<string> initial){var state=new HashSet<string>(initial);for(int i=0;i<path.Count;i++){var after=path[i].Apply(state);if(!Motion(Positions[Location(state)],Positions[Location(after)],Math.Max(Radius(state),Radius(after))))return i;state=after;}return -1;}
 public static string[] Run(string domainText,string problemText){
  var checks=new List<string>();Action<bool,string> require=(ok,name)=>{if(!ok)throw new Exception(name);checks.Add(name);};
  var domain=Parse(domainText);var problem=Parse(problemText);var objects=Typed(Section(problem,":objects").Items.Skip(1));var ops=new List<Op>();foreach(var action in domain.Items.Where(x=>x.Items.Count>0&&x.Items[0].Atom==":action")){var pars=action.Items[action.Items.FindIndex(x=>x.Atom==":parameters")+1];Instantiate(action,Typed(pars.Items),objects,ops,0,new Dictionary<string,string>());}ops=ops.OrderBy(x=>x.Name,StringComparer.Ordinal).ToList();
  var initial=new HashSet<string>(Section(problem,":init").Items.Skip(1).Select(x=>x.ToString()));string goal=Section(problem,":goal").Items[1].ToString();
  string[] candidate={"(move-empty delivery pickup)","(pick parcel pickup)","(move-loaded parcel pickup delivery)","(place parcel delivery)"};string[] revised={"(move-empty delivery pickup)","(pick parcel pickup)","(move-loaded parcel pickup upper-left)","(move-loaded parcel upper-left upper-right)","(move-loaded parcel upper-right delivery)","(place parcel delivery)"};
  var pick=ops.Single(x=>x.Name==candidate[1]);require(!pick.Applicable(initial),"Grounded pick exists but is initially inapplicable");var atPickup=ops.Single(x=>x.Name==candidate[0]).Apply(initial);require(pick.Applicable(atPickup),"Empty move makes pickup applicable");var holding=pick.Apply(atPickup);require(holding.Contains("(holding parcel)")&&!holding.Contains("(hand-empty)")&&!holding.Contains("(package-at parcel pickup)")&&holding.Contains("(robot-at pickup)"),"Pick add/delete effects and unchanged robot location");
  var first=Search(initial,goal,ops);require(first.Select(x=>x.Name).SequenceEqual(candidate),"Authored PDDL independently yields exact four-action BFS candidate");require(Validate(first,initial)==2,"Third candidate action fails swept-disk validation");
  var refined=new HashSet<string>(initial);refined.Remove("(can-loaded pickup delivery)");require(refined.Contains("(can-empty pickup delivery)")&&refined.Contains("(can-loaded delivery pickup)"),"Refinement preserves empty and reverse loaded permissions");var second=Search(refined,goal,ops);require(second.Select(x=>x.Name).SequenceEqual(revised),"Refined model independently yields exact six-action BFS plan");require(Validate(second,refined)==-1,"Every revised motion and footprint change is valid");
  var final=new HashSet<string>(refined);foreach(var op in second)final=op.Apply(final);require(final.Contains(goal)&&final.Contains("(hand-empty)")&&!final.Contains("(holding parcel)"),"Place achieves delivery goal and releases parcel");require(initial.Contains("(robot-at delivery)")&&!initial.Contains("(holding parcel)")&&initial.Contains("(can-loaded pickup delivery)"),"Independent hypothetical checks leave original state unchanged");
  var a=Positions["pickup"];var b=Positions["delivery"];require(Math.Abs(Rectangles.Min(r=>SegmentRect(a,b,r))-.2)<1e-12,"Shortcut centerline clearance is 0.20 m");require(Motion(a,b,.12)&&!Motion(a,b,.2)&&!Motion(a,b,.25),"Empty passes; tangent and loaded footprints fail");require(!Motion(new[]{.12,1.0},new[]{1.0,1.0},.12)&&Motion(new[]{.13,1.0},new[]{1.0,1.0},.12),"Workspace contact rejected; strictly inside accepted");
  require(initial.Count(x=>x.StartsWith("(can-"))==16,"Sixteen directed/load-specific permissions; at most seventeen searches");return checks.ToArray();
 }
}
